      "topic": {
        "text": "Incorrect ordering of conditional statements causes numbers divisible by both 5 and 3 to output only 'fizz'",
        "refs": ["Q0004"]
      },
      "explanation_type": null,
      "explanation_text": {
        "text": "When the first condition checks only divisibility by 5 and is placed before the combined check for 5 and 3, a number like 15 satisfies the first condition, so 'fizz' is printed and the later else‑if branches are skipped.",
        "refs": ["Q0004"]
      }
    }
  ],
  "examples": [
    {
      "exemplifies": {
        "text": "Program output for various inputs",
        "refs": ["Q0004"]
      },
      "example_type": null,
      "example_text": {
        "text": "Input 5 → fizz; Input 10 → fizz; Input 3 → buzz; Input 15 → fizz (incorrect; should be fizzbuzz)",
        "refs": ["Q0004"]
      }
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "A number is divisible by 5 if the remainder of the number divided by 5 is zero.",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "A number is divisible by 3 if the remainder of the number divided by 3 is zero.",
        "refs": ["Q0003"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "If a number is divisible by both 5 and 3, the correct output should be 'fizzbuzz'.",
        "refs": ["Q0001"]
      },
      "fact_type": null
    }
  ],
